/** UI-only operations (SPEC 10.3). Session cookie only; tokens are refused. */
export const uiOnly = {
  login: (returnTo = '/'): void => { window.location.href = '/auth/login?return_to=' + encodeURIComponent(returnTo); },
  logout: (): Promise<{ ok: boolean }> => call('POST', '/ui/logout', {}, []),
  mint_api_token: (input: { name: string; scopes: Array<'read' | 'write' | 'publish' | 'manage' | 'admin'>; expires_in_days?: number | null }): Promise<{ id: string; token: string; name: string; scopes: string[]; expires_at: number | null }> => call('POST', '/ui/tokens', input, []),
  revoke_api_token: (input: { id: string }): Promise<{ revoked: boolean }> => call('DELETE', '/ui/tokens/{id}', input, ['id']),
  revoke_mcp_connection: (input: { id: string }): Promise<{ revoked: boolean }> => call('DELETE', '/ui/connections/{id}', input, ['id']),
} as const;
